    steps: ['Abra o catálogo oficial e leia a descrição de um plugin.', 'No Code, adicione o marketplace com o primeiro comando abaixo.', 'Instale o plugin de exemplo com o segundo comando.', 'Confira os recursos e teste uma tarefa com dados fictícios.'],
    prompt: 'claude plugin marketplace add anthropics/knowledge-work-plugins\nclaude plugin install sales@knowledge-work-plugins',
