export const glossary = [
  ['Skill', 'Um procedimento reutilizável descrito em SKILL.md, com recursos e scripts opcionais.'],
  ['Plugin', 'Um pacote que pode reunir skills, comandos, agentes e integrações.'],
  ['Conector', 'Uma integração que permite consultar dados ou executar ações em outro aplicativo.'],
  ['MCP', 'Model Context Protocol: padrão de comunicação entre clientes de IA e servidores de ferramentas e contexto.'],
  ['Hook', 'Um comportamento configurado para responder a um evento da ferramenta.'],
  ['CLI', 'Interface de linha de comando: um programa usado por comandos no terminal.'],
  ['Prompt', 'O pedido e as instruções enviados ao modelo para orientar uma tarefa.'],
  ['Contexto', 'Informações disponíveis para interpretar e executar a tarefa.'],
  ['Diff', 'Comparação que mostra linhas adicionadas, removidas ou modificadas em arquivos.'],
  ['Markdown', 'Formato de texto simples com marcações para títulos, listas, links e código.'],
  ['YAML', 'Formato de dados legível usado, por exemplo, nos metadados de uma skill.'],
  ['Idempotência', 'Propriedade de um fluxo que pode ser repetido sem produzir efeitos adicionais indesejados.'],
];
